import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { test, expect } from '@playwright/test';

/**
 * The prototype is one HTML file opened from `file://`: no server, no network.
 * It is generated by `npm run build:proto` (CI runs that before `test:e2e`).
 */
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const protoFile = path.join(root, 'design', 'prototype', 'index.html');

test.use({ locale: 'zh-CN', viewport: { width: 1440, height: 900 } });
test.describe.configure({ timeout: 120_000 });

test('prototype runs from file:// with mock data, no network and no console errors', async ({ page }) => {
  expect(
    fs.existsSync(protoFile),
    'prototype build missing: run `npm run build:proto` first',
  ).toBe(true);

  const consoleErrors = [];
  const pageErrors = [];
  const external = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') consoleErrors.push(msg.text());
  });
  page.on('pageerror', (err) => pageErrors.push(err.message));
  page.on('request', (req) => {
    const url = req.url();
    if (!/^(file|data|blob):/i.test(url)) external.push(url);
  });

  await page.goto(pathToFileURL(protoFile).href);
  await expect(page.getByTestId('next-app')).toBeVisible();
  await expect(page.getByTestId('next-sidebar')).toBeVisible();
  await expect(page.getByTestId('next-ws-node')).toHaveCount(2);

  // Seeded rich history: markdown, tool groups, a failed tool, path chips, model name, git info.
  await expect(page).toHaveURL(/#\/c\/c-rich$/);
  await expect(page.getByTestId('next-status')).toContainText('重构会话列表的加载逻辑');
  await expect(page.getByTestId('next-composer-input')).toHaveAttribute('placeholder', '描述任务');
  await expect(page.getByTestId('next-composer-attach')).toBeVisible();
  await expect(page.getByTestId('next-composer-newline')).toHaveCount(0);
  await page.getByTestId('next-composer-input').fill('把空对话的输入框固定到底部');
  await expect(page.getByTestId('next-composer-newline')).toHaveText('Shift+Enter 换行');
  await page.getByTestId('next-composer-input').fill('');
  await expect(page.getByTestId('next-composer-newline')).toHaveCount(0);
  await page.locator('[data-testid=next-conv-row][data-id="c-docs"]').click();
  await expect(page.getByTestId('next-context-banner')).toBeVisible();
  await expect(page.getByTestId('next-context-chip')).toHaveClass(/is-warn/);
  await expect(page.getByTestId('next-context-chip')).toHaveText('86%');
  await expect(page.getByTestId('next-context-new')).toBeVisible();
  await page.locator('[data-testid=next-conv-row][data-id="c-rich"]').click();
  await expect(page.getByTestId('next-tool-group')).toHaveCount(2);
  await expect(page.getByTestId('next-message-chip').first()).toContainText('Grok 4.6');
  await expect(page.getByTestId('next-status-git-branch')).toHaveText('main');
  await expect(page.getByTestId('next-status-git-diff')).toContainText('+42');
  await expect(page.locator('.md-table')).toHaveCount(1);
  await expect(page.locator('.md-path').first()).toBeVisible();
  // Tool groups start collapsed; expanding shows read/search/bash/edit rows.
  await expect(page.getByTestId('next-tool-row').first()).not.toBeVisible();
  await page.getByTestId('next-tool-group-summary').first().click();
  await expect(page.getByTestId('next-tool-group-list').first().getByTestId('next-tool-row')).toHaveCount(4);
  await expect(page.getByTestId('next-tool-row-status').first()).toContainText('失败');
  await page.getByTestId('next-tool-group-summary').nth(1).click();
  await expect(
    page.getByTestId('next-tool-group').nth(1)
      .getByTestId('next-tool-row').filter({ hasText: 'store.ts' })
      .getByTestId('next-tool-row-added'),
  ).toContainText('+8');

  // Workspace rows expand/collapse in place.
  const websiteNode = page.getByTestId('next-ws-node').filter({ hasText: 'website' });
  const websiteToggle = websiteNode.getByTestId('next-ws-toggle');
  await expect(websiteToggle).toHaveAttribute('aria-expanded', 'false');
  await websiteToggle.click();
  await expect(websiteToggle).toHaveAttribute('aria-expanded', 'true');
  await expect(websiteNode.getByTestId('next-conv-row')).toHaveCount(2);
  await websiteToggle.click();
  await expect(websiteToggle).toHaveAttribute('aria-expanded', 'false');

  // Sidebar switches conversations without a reload.
  await page.locator('[data-testid=next-conv-row][data-id="c-tests"]').click();
  await expect(page).toHaveURL(/#\/c\/c-tests$/);
  await expect(page.getByTestId('next-status')).toContainText('heartbeat 要不要单测');
  const rowsBefore = await page.getByTestId('next-conv-row').count();

  // New chat: first send creates the conversation, adds a sidebar row and navigates.
  await page.getByTestId('next-new-chat').click();
  await expect(page).toHaveURL(/#\/w\/ws-weft\/new$/);
  await expect(page.getByTestId('next-draft-hint')).toContainText('weft');
  await expect(page.getByTestId('next-ws-chip')).toContainText('weft');
  // The draft workspace chip really retargets the conversation.
  await page.getByTestId('next-ws-chip').click();
  await expect(page.getByTestId('next-ws-chip-menu')).toBeVisible();
  await expect(page.getByTestId('next-ws-chip-option')).toHaveCount(2);
  await page.locator('[data-testid=next-ws-chip-option][data-id="ws-website"]').click();
  await expect(page).toHaveURL(/#\/w\/ws-website\/new$/);
  await expect(page.getByTestId('next-ws-chip')).toContainText('website');
  await expect(page.getByTestId('next-draft-hint')).toContainText('website');
  await page.getByTestId('next-ws-chip').click();
  await page.locator('[data-testid=next-ws-chip-option][data-id="ws-weft"]').click();
  await expect(page).toHaveURL(/#\/w\/ws-weft\/new$/);
  await expect(page.getByTestId('next-ws-chip')).toContainText('weft');
  await page.getByTestId('next-composer-input').fill('看一下 store.ts 的加载顺序');
  await page.getByTestId('next-send').click();
  await expect(page.getByTestId('next-thread-pending')).toBeVisible();
  await expect(page).toHaveURL(/#\/c\/c-\d+$/);
  const cid = page.url().split('/c/')[1];
  const newRow = page.locator(`[data-testid=next-conv-row][data-id="${cid}"]`);
  await expect(page.getByTestId('next-item-user')).toContainText('看一下 store.ts');
  await expect(page.getByTestId('next-run-status')).toHaveText('运行中');
  await expect(page.getByTestId('next-elapsed')).toBeVisible({ timeout: 10_000 });
  await expect(page.getByTestId('next-stop')).toBeVisible();
  await expect(newRow).toHaveAttribute('data-status', 'running');

  // A tool record arrives before the text, then the answer streams to completion.
  await expect(page.getByTestId('next-tool-group').first()).toBeVisible({ timeout: 20_000 });
  await page.getByTestId('next-tool-group-summary').first().click();
  await expect(page.getByTestId('next-tool-row').first()).toBeVisible();
  await expect(page.getByTestId('next-stream-spin')).toHaveCount(1, { timeout: 20_000 });
  await expect(page.getByTestId('next-run-status')).toHaveText('完成', { timeout: 30_000 });
  await expect(page.getByTestId('next-stop')).toHaveCount(0);
  await expect(page.getByTestId('next-item-assistant').last()).toHaveAttribute('data-streaming', 'false');
  await expect(page.getByTestId('next-item-assistant').last()).not.toHaveAttribute('data-id', /^live:/);
  await expect(page.getByTestId('next-conv-row')).toHaveCount(rowsBefore + 1);
  await expect(newRow).toHaveAttribute('data-status', 'idle');
  // Context usage grows from 0% once the run is recorded.
  await expect(page.getByTestId('next-context-chip')).not.toContainText('0%');

  // Sending while running queues the steer; it lands after the current step.
  await page.getByTestId('next-composer-input').fill('跑一下测试');
  await page.getByTestId('next-send').click();
  await expect(page.getByTestId('next-stop')).toBeVisible({ timeout: 10_000 });
  await page.getByTestId('next-composer-input').fill('顺便看下 README');
  await page.getByTestId('next-send').click();
  await expect(page.getByTestId('next-run-status')).toHaveText('完成', { timeout: 40_000 });
  await expect(page.getByTestId('next-item-user')).toHaveCount(3);
  await expect(page.getByTestId('next-item-user').last()).toContainText('顺便看下 README');

  // Stop ends a run and gives the composer back.
  await page.getByTestId('next-composer-input').fill('再跑一遍测试');
  await page.getByTestId('next-send').click();
  await expect(page.getByTestId('next-stop')).toBeVisible({ timeout: 10_000 });
  await page.waitForTimeout(900);
  await page.getByTestId('next-stop').click();
  await expect(page.getByTestId('next-stop')).toHaveCount(0);
  await expect(page.getByTestId('next-run-status')).toHaveText('已停止');
  await expect(page.getByTestId('next-send')).toBeVisible();

  // The model menu really switches the conversation model.
  await page.getByTestId('next-model-chip').click();
  await expect(page.getByTestId('next-model-menu')).toBeVisible();
  await expect(page.getByTestId('next-model-option')).toHaveCount(3);
  await page.locator('[data-testid=next-model-option][data-model="grok-4"]').click();
  await expect(page.getByTestId('next-model-chip')).toContainText('Grok 4');

  expect(pageErrors, 'page has no uncaught errors').toEqual([]);
  expect(consoleErrors, 'page has no console errors').toEqual([]);
  expect(external, 'page makes no external requests').toEqual([]);
});
